(796, 157, '_form', '<div class=\"form-orcamento\">\n<h2>Orçamento</h2>\n<p>Preencha o formulário abaixo corretamente que entraremos em contato assim que possível.</p>\n\n<div class=\"rows\">\n\n<div class=\"control-group\">\n    <label>Nome *</label>\n    [text* your-name class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>E-mail *</label>\n    [email* your-email class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>Telefone</label>\n    [text tel-685 class:tel class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>Empresa</label>\n    [text empresa-685 class:form-control]\n</div>\n\n<div class=\"control-group2\">\n    <label>Altura total <small>(Soma total das alturas de todas as torres que vai utilizar)</small></label>\n    [text alturatotal-685 class:form-control]\n</div>\n<div class=\"clearfix\">\n    <div class=\"control-group3\">\n        <label>Largura da base Torre</label>\n        [radio largura-698 \"1,0m x 1,0m\" \"1,5m x 1,0m\" \"1,5m x 1,5m\" \"2,0m x 2,0m\"]\n    </div>\n    <div class=\"control-group3\">\n        <label>Acessórios NR 18</label>\n        [checkbox acessorios-698 exclusive  \"Escadas\" \"Rodapés\" \"Guarda-corpo\"]\n    </div>\n    <div class=\"control-group3\">\n        <label>Período de locação</label>\n        [radio periodo-698 \"07 dias\" \"15 dias\" \"30 dias\"]\n    </div>\n</div>\n\n<div class=\"control-group4\">\n    <label>Sapatas fixas</label>\n    [text sapatas1-685 class:form-control]\n</div>\n\n<div class=\"control-group4\">\n    <label>Sapatas ajustáveis</label>\n    [text sapatas2-685 class:form-control]\n</div>\n\n<div class=\"control-group4\">\n    <label>Rodas</label>\n    [text rodas-685 class:form-control]\n</div>\n\n<div class=\"control-group4\">\n    <label>Pranchas metálicas</label>\n    [text pranchas-685 class:form-control]\n</div>\n\n<div class=\"control-group2\">\n    <label>Observações <small>(opcional)</small></label>\n    [textarea obs-685 40x5 class:form-control] \n</div>\n\n<div class=\"control-group\">\n    <label>CEP para calculo do frete</label>\n    [text cep-685 class:cep class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <div class=\"checkbox\">[checkbox retirar-685 \"Desejo retirar o equipamento no local\"]</div>\n</div>\n\n<div class=\"control-group2\">\n<button type=\"submit\" class=\"wpcf7-form-control wpcf7-submit\">Enviar <span class=\"glyphicon glyphicon-send\"></span></button>\n</div>\n\n</div>\n</div>'),
(797, 157, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:62:\"Loctubo - Pedido de orçamento para Andaime Tubular tipo torre\";s:6:\"sender\";s:32:\"Loctubo <contato@loctubo.com.br>\";s:9:\"recipient\";s:22:\"contato@loctubo.com.br\";s:4:\"body\";s:458:\"Pedido de orçamento para Andaime Tubular tipo torre:\n\nDe: [your-name] <[your-email]>\nTelefone: [tel-685]\nEmpresa: [empresa-685]\n\nAltura total: [alturatotal-685]\nLargura: [largura-698]\nAcessórios NR 18: [acessorios-698]\nPeríodo de locação: [periodo-698]\nSapatas fixas: [sapatas1-685]\nSapatas ajustáveis: [sapatas2-685]\nRodas: [rodas-685]\nPranchas metálicas: [pranchas-685]\n\nCEP: [cep-685]\nIrá retirara no local: [retirar-685]\n\nObservações:\n[obs-685]\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
