INSERT INTO `wplc_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(1424, 318, '_form', '<div class=\"form-orcamento\">\n<h2>Orçamento</h2>\n<p>Preencha o formulário abaixo corretamente que entraremos em contato assim que possível.</p>\n\n<div class=\"rows\">\n\n<div class=\"control-group\">\n    <label>Nome *</label>\n    [text* your-name class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>E-mail *</label>\n    [email* your-email class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>Telefone</label>\n    [text tel-685 class:tel class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <label>Empresa</label>\n    [text empresa-685 class:form-control]\n</div>\n\n<div class=\"clearfix\">  \n    <div class=\"control-group\">\n        <label>Modelo</label>\n        [radio modelo-685 \"Rompedor \" \"Perfurador (Equipado com Porta-Broca, disponível somente para 10/11Kg)\"]\n    </div>\n    <div class=\"control-group\">\n        <label>Período de locação</label>      \n        [radio periodo-685 \"03 dias - Equipado com 02 ferramentas\" \"05 dias - Equipado com 02 ferramentas\" \"07 dias - Equipado com 02 ferramentas\" \"15 dias - Equipado com 03 ferramentas\" \"30 dias - Equipado com 04 ferramentas\"]\n    </div>\n</div>\n\n<div class=\"control-group2\">\n    <label>Observações <small>(opcional)</small></label>\n    [textarea obs-685 40x5 class:form-control] \n</div>\n\n<div class=\"control-group\">\n    <label>CEP para calculo do frete</label>\n    [text cep-685 class:cep class:form-control]\n</div>\n\n<div class=\"control-group\">\n    <div class=\"checkbox\">[checkbox retirar-685 \"Desejo retirar o equipamento no local\"]</div>\n</div>\n\n<div class=\"control-group2\">\n<button type=\"submit\" class=\"wpcf7-form-control wpcf7-submit\">Enviar <span class=\"glyphicon glyphicon-send\"></span></button>\n</div>\n\n</div>\n</div>'),
(1425, 318, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:77:\"Loctubo - Pedido de orçamento para Martelete elétrico demolidor Bosch 30 Kg\";s:6:\"sender\";s:32:\"Loctubo <contato@loctubo.com.br>\";s:9:\"recipient\";s:22:\"contato@loctubo.com.br\";s:4:\"body\";s:282:\"Pedido de orçamento para Martelete elétrico demolidor Bosch 30 Kg:\n\nDe: [your-name] <[your-email]>\nTelefone: [tel-685]\nEmpresa: [empresa-685]\n\nModelo: [modelo-685]\nPeríodo de locação: [periodo-685]\n\nCEP: [cep-685]\nIrá retirara no local: [retirar-685]\n\nObservações:\n[obs-685]\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
(1426, 318, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:0:\"\";s:6:\"sender\";s:0:\"\";s:9:\"recipient\";s:0:\"\";s:4:\"body\";s:0:\"\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(1427, 318, '_messages', 'a:23:{s:12:\"mail_sent_ok\";s:27:\"Agradecemos a sua mensagem.\";s:12:\"mail_sent_ng\";s:74:\"Ocorreu um erro ao tentar enviar sua mensagem. Tente novamente mais tarde.\";s:16:\"validation_error\";s:63:\"Um ou mais campos possuem um erro. Verifique e tente novamente.\";s:4:\"spam\";s:74:\"Ocorreu um erro ao tentar enviar sua mensagem. Tente novamente mais tarde.\";s:12:\"accept_terms\";s:72:\"Você deve aceitar os termos e condições antes de enviar sua mensagem.\";s:16:\"invalid_required\";s:24:\"O campo é obrigatório.\";s:16:\"invalid_too_long\";s:23:\"O campo é muito longo.\";s:17:\"invalid_too_short\";s:23:\"O campo é muito curto.\";s:12:\"invalid_date\";s:34:\"O formato de data está incorreto.\";s:14:\"date_too_early\";s:44:\"A data é anterior à mais antiga permitida.\";s:13:\"date_too_late\";s:44:\"A data é posterior à maior data permitida.\";s:13:\"upload_failed\";s:49:\"Ocorreu um erro desconhecido ao enviar o arquivo.\";s:24:\"upload_file_type_invalid\";s:59:\"Você não tem permissão para enviar esse tipo de arquivo.\";s:21:\"upload_file_too_large\";s:26:\"O arquivo é muito grande.\";s:23:\"upload_failed_php_error\";s:36:\"Ocorreu um erro ao enviar o arquivo.\";s:14:\"invalid_number\";s:34:\"O formato de número é inválido.\";s:16:\"number_too_small\";s:46:\"O número é menor do que o mínimo permitido.\";s:16:\"number_too_large\";s:46:\"O número é maior do que o máximo permitido.\";s:23:\"quiz_answer_not_correct\";s:39:\"A resposta para o quiz está incorreta.\";s:17:\"captcha_not_match\";s:35:\"O código digitado está incorreto.\";s:13:\"invalid_email\";s:45:\"O endereço de e-mail informado é inválido.\";s:11:\"invalid_url\";s:19:\"A URL é inválida.\";s:11:\"invalid_tel\";s:35:\"O número de telefone é inválido.\";}'),
